def evaluate(definitions: list[Definition], messages: list[dict[str, Any]]) -> dict[str, Any]:
    """Return a decision: allow, block (with reason), or modify (with the full messages)."""
    working = copy.deepcopy(messages)
    acted: list[dict[str, Any]] = []

    for definition in definitions:
        total = 0
        for slot in list(_slots(working)):
            result = definition.module.apply(definition.state, _get(working, slot))
            if result.block_reason is not None:
                acted.append(_entry(definition, "block", 1))
                return {
                    "decision": "block",
                    "reason": f"{definition.name}: {result.block_reason}",
                    "messages": None,
                    "acted": acted,
                }
            if result.matches:
                _set(working, slot, result.text)
                total += result.matches
        if total:
            acted.append(_entry(definition, definition.action, total))

    if working != messages:
        return {"decision": "modify", "reason": None, "messages": working, "acted": acted}
    return {"decision": "allow", "reason": None, "messages": None, "acted": acted}

