@app.post("/v1/check", dependencies=[Depends(require_token)])
def check(body: CheckRequest, request: Request) -> Decision:
    # A plain def: FastAPI runs it in a worker thread, so CPU-bound regex work does not block /health.
    result = evaluate(request.app.state.definitions, body.messages)
    logger.info("check decision=%s acted=%s", result["decision"], [entry["name"] for entry in result["acted"]])
    return result
